INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('addac107', 'general', 'https://takazudomodular.com/products/addac107-acid-source-intro/', '# ADDAC System: ADDAC107 ACID Source' || char(10) || '' || char(10) || '- category: general' || char(10) || '- product-url: https://takazudomodular.com/products/addac107-acid-source-intro/' || char(10) || '- aliases: ADDAC107, ADDAC 107, addac107, ADDAC107 ACID Source, ACID Source, acid source' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || 'ADDAC107 ACID Sourceは、TB-303を彷彿とさせるアシッドサウンドを生み出すモジュール。VCO／VCF／VCAが1モジュール内にコンパクトにまとまっており、VCAの独特なクリップサウンド設計がフィルターのレゾナンスと噛み合うのが特徴。完成品。' || char(10) || '' || char(10) || '## Manual' || char(10) || '' || char(10) || '- ADDAC System: ADDAC107 ACID Source Manual 日本語訳付き: https://takazudomodular.com/manuals/addac107-acids/' || char(10) || '' || char(10) || 'Intro text: こちらのADDAC107、当店の方で英語マニュアルに日本語訳を付けたものを以下にて公開しています。合わせてご参考いただけると幸いです。' || char(10) || '' || char(10) || '## Guides' || char(10) || '' || char(10) || '- ADDAC System: ADDAC107 ACID Source 紹介／解説: https://takazudomodular.com/products/addac107-acid-source-intro/' || char(10) || '' || char(10) || 'Intro text: ADDAC107について、当店サイトに紹介／解説記事を用意しております。VCAのクリップサウンドや内蔵フィルターとの組み合わせなど、このモジュールの特徴的な部分の解説をしておりますので、よろしければご参考にしてください。' || char(10) || '' || char(10) || '## Notes (additional)' || char(10) || '' || char(10) || 'The official ADDAC107 demo video (https://youtu.be/6W3fEzyQJ4A) and a session video using ADDAC107 (https://youtu.be/h8X_eiDTypQ) are already embedded in the intro article at `/products/addac107-acid-source-intro/`, so do NOT add an Extra Resources section to the message — it makes the message verbose and redundant.' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
