INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('addac207-quantizer', 'general', 'https://takazudomodular.com/products/addac207-quantizer-intro/', '# ADDAC System: ADDAC207 Intuitive Quantizer' || char(10) || '' || char(10) || '- category: general' || char(10) || '- product-url: https://takazudomodular.com/products/addac207-quantizer-intro/' || char(10) || '- aliases: ADDAC207, ADDAC 207, addac207, ADDAC207 Intuitive Quantizer, Intuitive Quantizer, addac207-quantizer' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || 'ADDAC207 Intuitive Quantizerは、4ボイスの直感的な（intuitive）操作のクオンタイザー。複数のオシレーターへ個別の1V/Octを渡せるほか、カスタムスケールの定義やコード生成用のノート間オフセット設定、11のユーザープリセット保存などが可能。パフォーマンス中の操作に適したサイズ感が特徴。完成品。奥行き52mmと深いのでケースの深さに注意。' || char(10) || '' || char(10) || '## Manual' || char(10) || '' || char(10) || '- ADDAC System: ADDAC207 Intuitive Quantizer Manual 日本語訳付き: https://takazudomodular.com/manuals/addac207-quantizer' || char(10) || '' || char(10) || 'Intro text: こちらのADDAC207、当店の方で英語マニュアルに日本語訳を付けたものを以下にて公開しています。合わせてご参考いただけると幸いです。' || char(10) || '' || char(10) || '## Guides' || char(10) || '' || char(10) || '- ADDAC System: ADDAC207 Intuitive Quantizer 紹介／解説: https://takazudomodular.com/products/addac207-quantizer-intro/' || char(10) || '' || char(10) || 'Intro text: ADDAC207について、当店サイトに紹介／解説記事を用意しております。4ボイスの扱いやカスタムスケール・コード生成など、このモジュールの魅力的なポイントを解説しておりますので、よろしければご参考にしてください。' || char(10) || '' || char(10) || '## Videos' || char(10) || '' || char(10) || '- ADDAC207 セッション動画（OXI ONE + Vector Wave）: https://youtu.be/5iHzqy926mw' || char(10) || '' || char(10) || '## Notes (additional)' || char(10) || '' || char(10) || 'The session video (https://youtu.be/5iHzqy926mw) is already embedded in the intro article at `/products/addac207-quantizer-intro/`, so do NOT add a separate Extra Resources / Videos section to the message — pointing to the intro article covers it and keeps the message from getting verbose.' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
