INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('addac304', 'general (built) / diy (kit)', 'https://takazudomodular.com/products/addac304-manual-gates-intro/', '# ADDAC System: ADDAC304 Manual Gates' || char(10) || '' || char(10) || '- category: general (built) / diy (kit)' || char(10) || '- product-url: https://takazudomodular.com/products/addac304-manual-gates-intro/' || char(10) || '- aliases: ADDAC304, ADDAC 304, addac304, addac304-built, addac304-diy, Manual Gates' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || 'ADDAC304 Manual Gatesは、8つのモーメンタリスイッチを持つマニュアルGate出力モジュール。ADDAC305の兄弟モジュールで、こちらはモーメンタリ式（押している間だけGate出力）。2／4／5／7番にはCV入力ジャックがあり、接続時はボタンを押している間だけ入力CVをそのまま出力する。完成品とDIYキットの両方を取り扱い。モジュール本体には特にマニュアルは用意されていません（紹介記事内に解説あり）。' || char(10) || '' || char(10) || '## Product Intro' || char(10) || '' || char(10) || '- ADDAC System: ADDAC304 Manual Gates 紹介: https://takazudomodular.com/products/addac304-manual-gates-intro/' || char(10) || '' || char(10) || 'Intro text: ADDAC304について、当店サイトに紹介／解説記事を用意しております。よろしければご参考にしてください。' || char(10) || '' || char(10) || '## Manual (diy only)' || char(10) || '' || char(10) || '- ADDAC304 Manual Gates: DIY Guide 日本語訳: https://takazudomodular.com/manuals/addac304-manualgates-diy/' || char(10) || '' || char(10) || 'Intro text: DIYキットの組み立てガイドについて、ADDAC System公式の英語版DIYガイドに日本語訳を付けたものを当店サイトにて公開しています。組み立ての際にはこちらをご参考にしていただけると幸いです。' || char(10) || '' || char(10) || '## Build Guide (diy only)' || char(10) || '' || char(10) || '- ADDAC304 Manual Gates: DIY Guide 日本語訳: https://takazudomodular.com/manuals/addac304-manualgates-diy/' || char(10) || '' || char(10) || '## Guides' || char(10) || '' || char(10) || '- ADDAC304 & ADDAC305 Manual Gates and Latches ガイド: https://takazudomodular.com/guides/series/addac304-305-guide/' || char(10) || '' || char(10) || 'Intro text: ほか、ADDAC304とADDAC305の各種機能について、ガイド記事のシリーズを用意しております。こちらモジュールの理解の際にご参照いただけますと幸いです。' || char(10) || '', 