INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('addac306', 'general', 'https://takazudomodular.com/products/addac306-vc-transitions-intro/', '# ADDAC System: ADDAC306 VC Transitions' || char(10) || '' || char(10) || '- category: general' || char(10) || '- product-url: https://takazudomodular.com/products/addac306-vc-transitions-intro/' || char(10) || '- aliases: ADDAC306, ADDAC 306, addac306, ADDAC306 VC Transitions, VC Transitions, vc transitions' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || 'ADDAC306 VC Transitionsは、1本のスライダー（または1つのCV入力）で5チャンネルのCVを同時にスイープできる、8HPの電圧制御トランジション／マクロコントローラー。各チャンネルに個別のレンジ・向きを設定でき、ひとつの操作で複数パラメーターをまとめてモーフィングできる。完成品。モジュール本体に専用マニュアルはなし（紹介記事内に解説あり。zmanualsにも翻訳マニュアルなし）。' || char(10) || '' || char(10) || '## Guides' || char(10) || '' || char(10) || '- ADDAC System: ADDAC306 VC Transitions 紹介／解説: https://takazudomodular.com/products/addac306-vc-transitions-intro/' || char(10) || '' || char(10) || 'Intro text: ADDAC306について、当店サイトに紹介／解説記事を用意しております。インターフェースの概要や活用例、DivKid氏によるデモ動画も掲載しておりますので、よろしければご参考にしてください。' || char(10) || '' || char(10) || '## Notes (additional)' || char(10) || '' || char(10) || 'The DivKid demo video (https://youtu.be/SbQuvTydYws) is already embedded in the intro article at `/products/addac306-vc-transitions-intro/`, so do NOT add a separate Extra Resources / Videos section to the message — pointing to the intro article covers the video too.' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
