INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('recovery-analog-kick', 'general', 'https://takazudomodular.com/products/recovery-analog-kick-intro/', '# Recovery Effects And Devices: Analog Kick' || char(10) || '' || char(10) || '- category: general' || char(10) || '- product-url: https://takazudomodular.com/products/recovery-analog-kick-intro/' || char(10) || '- aliases: Analog Kick, Recovery Analog Kick, recovery-analog-kick' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || 'Recovery Effects And Devices製、アナログサウンドを手軽に扱える3HPの小型キックモジュール。FUNDAMENTAL（ピッチ、CV対応）とCONTOUR（減衰・音色）の2パラメーターで、タムのようなアタック感のあるパーカッションから、TR-808由来のベース的なキックサウンドまで生成可能。マニュアルは現状未翻訳。' || char(10) || '' || char(10) || '## Guides' || char(10) || '' || char(10) || '- 紹介記事: https://takazudomodular.com/products/recovery-analog-kick-intro/' || char(10) || '' || char(10) || '## Videos' || char(10) || '' || char(10) || '- 公式デモ動画（Recovery Effects And Devices）: https://youtu.be/8htW4kW0aZY' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
