INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('ryk-algo', 'general', 'https://takazudomodular.com/products/ryk-algo/', '# RYK Modular: ALGO' || char(10) || '' || char(10) || '- category: general' || char(10) || '- product-url: https://takazudomodular.com/products/ryk-algo/' || char(10) || '- aliases: RYK Modular ALGO, RYK ALGO, ALGO, ryk-algo, ryk algo' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || 'Hand-built by Takazudo Modular from the official RYK Modular DIY kit (販売はメーカー許可済み)。完成後に動作確認を一通り行ったうえで出品しています。万が一おかしな点があればご連絡いただきたい旨を添えると安心です。' || char(10) || '' || char(10) || '## Guides' || char(10) || '' || char(10) || '- RYK Modular: ALGO 紹介／解説: https://takazudomodular.com/products/ryk-algo/' || char(10) || '' || char(10) || 'Intro text: ALGOについて、当店サイトに紹介／解説記事を用意しております。FMシンセとしての特長や、同じくRYKのVector Waveとの違いなどにも触れていますので、よろしければご参考にしてください。' || char(10) || '' || char(10) || '## Manual' || char(10) || '' || char(10) || '- RYK Modular: ALGO Manual 日本語訳付き: https://takazudomodular.com/manuals/ryk-algo' || char(10) || '' || char(10) || 'Intro text: こちらのALGO、当店の方で英語マニュアルに日本語訳を付けたものを以下にて公開しています。合わせてご参考いただけると幸いです。' || char(10) || '' || char(10) || '## Videos' || char(10) || '' || char(10) || '- ALGO解説動画（当店作成）: https://youtu.be/NGRYs1Wbfx8' || char(10) || '' || char(10) || 'Intro text: ALGOを実際に鳴らしつつざっくり解説した動画を当店の方で撮影しております。使い方の細かい部分にもひと通り触れておりますので、合わせてご参考にしていただけると幸いです。' || char(10) || '' || char(10) || '## Notes (additional)' || char(10) || '' || char(10) || 'Third-party reference videos (RYK Modular公式デモ, Cinematic Laboratory, Mylar Melodies, Takazudo''s hard techno session) are already embedded in the intro article at `/products/ryk-algo/`, so do NOT add an Extra Resources section to the message — it makes the message verbose and redundant.' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
