INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('wingie2', 'general', 'https://takazudomodular.com/products/wingie2-intro/', '# Meng Qi: Wingie2' || char(10) || '' || char(10) || '- category: general' || char(10) || '- product-url: https://takazudomodular.com/products/wingie2-intro/' || char(10) || '- aliases: Wingie2, Wingie 2, Wingie, meng-qi-wingie2, Meng Qi Wingie2, wingie2-intro' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || 'Meng Qi（孟奇）氏によるスタンドアロン型のステレオレゾネーター。モジュラーシンセではなく単体で動作する楽器で、内蔵マイク／LINE入力に対して4種類のレゾナンスモードで音響処理を行う。前面の鍵盤ボタンで直感的に音域を調整でき、MIDI TRS入力にも対応。' || char(10) || '' || char(10) || '## Manual' || char(10) || '' || char(10) || '- Wingie2 マニュアル（当店翻訳）: https://takazudomodular.com/manuals/wingie2' || char(10) || '' || char(10) || 'Intro text: Wingie2のマニュアルについて、当店にて日本語訳を用意しております。使い方等、こちらをご参考にしていただけると幸いです。' || char(10) || '' || char(10) || '## Guides' || char(10) || '' || char(10) || '- Meng Qi: Wingie2 紹介／解説記事: https://takazudomodular.com/products/wingie2-intro/' || char(10) || '- Wingie2ガイドシリーズ: https://takazudomodular.com/guides/series/wingie2-guide/' || char(10) || '' || char(10) || 'Intro text: Wingie2について、当店サイトに紹介／解説記事を用意しております。あわせて、公式動画に沿ってWingie2の使い方を解説するガイドシリーズも公開しておりますので、よろしければご参考にしてください。' || char(10) || '' || char(10) || '## Videos' || char(10) || '' || char(10) || '- マイク入力をオーディオソースとしたデモ: https://youtu.be/PDjr6rEkjYU' || char(10) || '- Polyモードを使ったセッション: https://youtu.be/hgVuH7URG2M' || char(10) || '- 各種モードを使ったセッション: https://youtu.be/S3By1-BCSGw' || char(10) || '' || char(10) || 'Intro text: 当店にてWingie2を鳴らしている動画もいくつか用意しております。どんな音が鳴る機材か感じていただけるかと思いますので、よろしければご参考にしてください。（いずれも上記の紹介記事内でも視聴いただけます）' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
