INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('zb40-intro', 'small', 'https://takazudomodular.com/products/zb40-intro/', '# zudo-block-40' || char(10) || '' || char(10) || '- category: small' || char(10) || '- product-url: https://takazudomodular.com/products/zb40-intro/' || char(10) || '- aliases: zudo-block-40, zb40, zudo block 40, zudo-block-40-red-lite' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || '40HP対応のアクリルボード製ユーロラックケースDIYキット（Takazudo Modular自社設計）。パネル・レール・金具一式の構成で、組み立てが必要。フラットに梱包できるためネコポス発送（small扱い）。組み立てが必要なため、build guideを必ず案内する。半田付けは不要なので、シンセDIY入門ガイドは案内しない。' || char(10) || '' || char(10) || '## Build Guide' || char(10) || '' || char(10) || '- zudo-block-40 / zudo-block-60 組み立て方法: https://takazudomodular.com/guides/how-to-build-zudo-block/' || char(10) || '' || char(10) || 'Intro text: 本品の組み立て方法ですが、以下にステップバイステップで組み立て手順をまとめております。こちらを参考にしつつ、組み立てをお願い致します。' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
