INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('zudo-3u-to-1u', 'small', 'https://takazudomodular.com/products/zudo-3u-to-1u-intro/', '# zudo-3u-to-1u' || char(10) || '' || char(10) || '- category: small' || char(10) || '- product-url: https://takazudomodular.com/products/zudo-3u-to-1u-intro/' || char(10) || '- aliases: zudo 3u to 1u, 3u-to-1u, 3u to 1u, コンバーターパネル' || char(10) || '' || char(10) || '## Notes' || char(10) || '' || char(10) || 'Intellijelフォーマットの1Uスロットに、3Uモジュール（最大4HP幅）を設置出来るようにするコンバーターパネルセット。パネル×3、M3ネジ／プラスチックワッシャ／ナット各12付属。ネコポス発送（small）。Intellijel 1U（39.65mm）対応／Pulplogic・Doepfer 1U（43.2mm）非対応。' || char(10) || '' || char(10) || '## Usage Guide (取り付け方法)' || char(10) || '' || char(10) || '本製品は、横に長く空いている穴部分へ、3Uモジュールを取り付けて使用します。このパネル自体にはネジを止めるタップ（ネジを支える形状の溝）がありませんので、付属のネジとナットを使用し、裏側でネジをナットで固定してご使用ください。' || char(10) || '' || char(10) || '## Guides' || char(10) || '' || char(10) || '- Takazudo Modular: zudo-3u-to-1u 紹介／解説記事: https://takazudomodular.com/products/zudo-3u-to-1u-intro/' || char(10) || '' || char(10) || 'Intro text: 詳しい使い方や設置例、対応フォーマット（Intellijel 1U）については、当店サイトの紹介記事にもまとめております。よろしければご参考にしてください。' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
