INSERT INTO product_refs (slug, category, product_url, body_md, version, updated_at, updated_by) VALUES ('zudo-rail', 'small', 'https://takazudomodular.com/products/zudo-rail-intro/', '# zudo-rail' || char(10) || '' || char(10) || '- category: small' || char(10) || '- product-url: https://takazudomodular.com/products/zudo-rail-intro/' || char(10) || '- aliases: zudo rail, ズドレール' || char(10) || '' || char(10) || '## Assembly Guide' || char(10) || '' || char(10) || '- zudo-rail 組み立て方法: https://takazudomodular.com/guides/how-to-build-zudo-rail/' || char(10) || '' || char(10) || 'Intro text: 組み立てにつきましては、以下をご参考に組み立ててくださいますよう、お願い致します。不明点等ありましたらお気軽にお声がけ頂けると幸いです。' || char(10) || '' || char(10) || '## Lite Version Renewal Notice (ALWAYS include for Lite variants)' || char(10) || '' || char(10) || 'When the purchased product is a **Lite** variant (e.g. "zudo-rail lite 60 set1"), ALWAYS append the following notice after the assembly guide section. The site photos have not been updated yet to reflect the renewed Lite rail design.' || char(10) || '' || char(10) || '```' || char(10) || 'それとこちらの商品の一部であるレールの本体の形状についてなのですが、写真にあるのは以下のLite版のものなのですが、' || char(10) || '' || char(10) || 'zudo-rail' || char(10) || 'https://takazudomodular.com/products/zudo-rail-intro/' || char(10) || '' || char(10) || 'この商品を直近でリニューアルしまして、ものとしてはほぼ同じなのですが、Nuts版のようにハネが付いたようなデザインの、新しいタイプのLite版レールをお送りさせて頂いています。サイトや商品写真の更新がおいついておらず、後からのご連絡になってしまいまして申し訳ないのですが、ものとしてはより使いやすいものかと考えておりまして、ご容赦願えればと存じます。' || char(10) || '```' || char(10) || '' || char(10) || '## Fragility Notice (ALWAYS include — Lite and Nuts variants)' || char(10) || '' || char(10) || 'Both **Lite** and **Nuts** rails are fragile (折れやすい). ALWAYS append the following notice for any zudo-rail purchase.' || char(10) || '' || char(10) || '```' || char(10) || 'なお、こちらのレールは構造上やや折れやすい部分がございまして、組み立てや取り付けの際は無理な力をかけないよう、お気を付け頂けますと幸いです。' || char(10) || '```' || char(10) || '', 1, 0, 'seed') ON CONFLICT(slug) DO NOTHING;
